@layer moduix.components {
  .root {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--moduix-spacing-1);
    width: var(--moduix-date-input-width, auto);
    max-width: 100%;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
  }

  .label {
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .control {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
    width: 100%;
    min-height: var(--moduix-date-input-control-height, var(--moduix-size-md));
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-date-input-radius, var(--moduix-radius-md));
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &[data-focus] {
      outline-color: var(--moduix-color-ring);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);

      &[data-focus] {
        outline-color: var(--moduix-color-destructive);
      }
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  .segmentGroup {
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-0-5);
    font-variant-numeric: tabular-nums;
  }

  .segment {
    min-width: 2ch;
    border-radius: var(--moduix-radius-sm);
    padding-inline: var(--moduix-spacing-1);
    text-align: center;
    outline: 0;
    cursor: default;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    &[data-editable] {
      cursor: text;
    }

    &[data-placeholder-shown] {
      color: var(--moduix-color-muted-foreground);
    }

    &:focus-visible {
      background-color: color-mix(in oklab, var(--moduix-color-ring) 18%, transparent);
      color: var(--moduix-color-foreground);
    }

    &[data-type='literal'] {
      min-width: auto;
      padding-inline: 0;
      color: var(--moduix-color-muted-foreground);
    }
  }

  .separator {
    color: var(--moduix-color-muted-foreground);
    user-select: none;
  }
}

import {
  DateInputContext,
  DateInputHiddenInput,
  DateInputSegmentContext,
  useDateInput,
  useDateInputContext,
} from '@ark-ui/vue/date-input';
import DateInput from './DateInput.vue';
import DateInputControl from './DateInputControl.vue';
import DateInputLabel from './DateInputLabel.vue';
import DateInputRootProvider from './DateInputRootProvider.vue';
import DateInputSegment from './DateInputSegment.vue';
import DateInputSegmentGroup from './DateInputSegmentGroup.vue';
import DateInputSegments from './DateInputSegments.vue';
import DateInputSeparator from './DateInputSeparator.vue';

export {
  DateInput,
  DateInputContext,
  DateInputControl,
  DateInputHiddenInput,
  DateInputLabel,
  DateInputRootProvider,
  DateInputSegment,
  DateInputSegmentContext,
  DateInputSegmentGroup,
  DateInputSegments,
  DateInputSeparator,
  useDateInput,
  useDateInputContext,
};

export type {
  DateInputContextProps,
  DateInputControlBaseProps,
  DateInputControlProps,
  DateInputDateValue,
  DateInputFocusChangeDetails,
  DateInputHiddenInputBaseProps,
  DateInputHiddenInputProps,
  DateInputLabelBaseProps,
  DateInputLabelProps,
  DateInputRootBaseProps,
  DateInputRootEmits,
  DateInputRootProps,
  DateInputRootProviderBaseProps,
  DateInputRootProviderProps,
  DateInputSegmentBaseProps,
  DateInputSegmentContextProps,
  DateInputSegmentGroupBaseProps,
  DateInputSegmentGroupProps,
  DateInputSegmentProps,
  DateInputSelectionMode,
  DateInputValueChangeDetails,
  UseDateInputContext,
  UseDateInputProps,
  UseDateInputReturn,
} from '@ark-ui/vue/date-input';
